# Scratch-only workflow/source contract checks; never runs a product or repository test.
from pathlib import Path
import ast, hashlib, json, re, subprocess, yaml
p=Path(__file__).resolve().parent
w=yaml.safe_load((p/'proposal/toolchain-m5-unit-analysis.yml').read_text()); h=(p/'proposal/reader-state-validation.sh').read_text()
checks=[]
def check(name,condition):
 assert condition,name
 checks.append(name)
j=w['jobs']['reader-state']; e=j['env']; s=j['steps']; private='bash chibi/.github/scripts/reader-state-validation.sh '
check('single dedicated job',list(w['jobs'])==['reader-state'])
check('pull request only',set(w.get('on',w.get(True)))=={'pull_request'})
check('normal PR events',w.get('on',w.get(True))['pull_request']=={'branches':['main'],'types':['opened','synchronize','reopened']})
check('read-only permission',w['permissions']=={'contents':'read'})
check('no superseding cancellation',w['concurrency']['cancel-in-progress'] is False)
check('dedicated concurrency group','host-m5-native-unit-' in w['concurrency']['group'])
check('same repository admission','head.repo.full_name == github.repository' in j['if'])
check('dedicated control branch','codex/host-m5-unit-validation-20261018' in j['if'])
check('fixed runner',j['runs-on']=='ubuntu-24.04')
check('outer job budget is separate',j['timeout-minutes']==45)
check('proposal is unarmed',e['READER_STATE_REVIEWED']=='false')
check('source pin explicitly pending',e['CANDIDATE_SHA']=='REQUIRES_REVIEWED_PRIVATE_CANDIDATE_SHA')
check('tree pin explicitly pending',e['CANDIDATE_TREE']=='REQUIRES_REVIEWED_PRIVATE_CANDIDATE_TREE')
check('dedicated private branch',e['SOURCE_BRANCH']=='refs/heads/codex/m5-snapshot-reader-validation-20261018')
check('control exact event head',e['CONTROL_SHA']=='${{ github.event.pull_request.head.sha }}')
check('base pinned',e['EXPECTED_BASE_SHA']=='bee5b54e159cce44ee52ca9439be587d9a95f5d2')
check('debug rejects before checkout',s[0]['env']=={'RUNNER_DEBUG_ENABLED':'${{ runner.debug }}'} and 'checkout-privacy-guard' in s[0]['run'])
check('checkout actions pinned',all(x['uses']=='actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1' for x in s if 'uses' in x and x['uses'].startswith('actions/checkout@')))
check('control immutable checkout',s[1]['with']=={'ref':'${{ env.CONTROL_SHA }}','fetch-depth':1,'persist-credentials':False,'path':'validation'})
c=s[2]['with']
check('private checkout one known repository',c['repository']=='waldnercharles/chibi')
check('existing source token only',c['token']=='${{ secrets.CHIBI_ENGINE_TOKEN }}')
check('no persisted credential',c['persist-credentials'] is False)
check('private branch checkout for quiet subject',c['ref']=='${{ env.SOURCE_BRANCH }}')
check('fresh shallow no-submodule checkout',c['fetch-depth']==1 and c['submodules'] is False and c['lfs'] is False and c['clean'] is False)
check('no source progress or tags',c['show-progress'] is False and c['fetch-tags'] is False)
check('source identity before helpers',s[3]['id']=='source_identity' and 'source_head' in s[3]['run'] and 'source_tree' in s[3]['run'] and 'source_status' in s[3]['run'])
calls=[x['run'][len(private):] for x in s if x.get('run','').startswith(private)]
check('only admitted phase calls',calls==['prepare','dependencies','configure','build','audit','execute','execute','execute','execute','collect','verdict'])
routes=[x for x in s if x.get('run')==private+'execute']
check('complete routes exactly once',[x['env']['SELECTOR'] for x in routes]==['language-package-snapshot-chibi','compiler-artifact','language-signature-reader-chibi','language-snapshot-reader-chibi'])
check('independent fail continuation',all(x['continue-on-error'] is True for x in routes))
check('outer per-step guard separate',all(x['timeout-minutes']==2 for x in routes))
check('no public dependency recipe',not any(z in (p/'proposal/toolchain-m5-unit-analysis.yml').read_text() for z in ['pip install','apt-get','nm ','readelf ','build.ninja','compile_commands','cmake -S']))
u=[x for x in s if x.get('uses','').startswith('actions/upload-artifact')]
check('exactly one upload',len(u)==1)
check('status-only pinned upload',u[0]['uses']=='actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9' and u[0]['with']['path']=='${{ runner.temp }}/chibi-m5-reader-state-status/status.json')
check('no wildcard artifacts','*' not in u[0]['with']['path'])
check('short retention',u[0]['with']['retention-days']==7)
check('source gate on all post-failure private work',all(x.get('if')=="always() && steps.source_identity.outcome == 'success'" for x in s if x.get('run') in [private+'collect',private+'verdict'] or 'upload-artifact' in x.get('uses','')))
check('writer audit precedes selectors',calls.index('audit')<calls.index('execute'))
check('query evidence private',all(x in h for x in ['codemodel-v2','cache-v2','toolchains-v1','CMAKE_EXPORT_COMPILE_COMMANDS=ON']))
check('ordinary product targets only','--target test_language' in h and '--target test_tools chibi-compiler-host' in h)
check('normal production boundary flags only',all(x not in h for x in ['CMAKE_C_FLAGS=','CMAKE_EXE_LINKER_FLAGS=','-ffunction-sections','-fdata-sections','-Wl,--gc-sections','strip --']))
check('compiler-only normal configuration',all(x in h for x in ['CHIBI_SDK_BUILD_COMPILER=ON','CHIBI_SDK_BUILD_NATIVE=OFF','CHIBI_SDK_BUILD_DESKTOP=OFF','CHIBI_ENABLE_SJLIT=ON']))
check('no runtime retries','mkdir "$WORK/execution-started-$SELECTOR"' in h and h.count('python3 tools/test_policy.py tool "$SELECTOR"')==1)
check('audit success required for runtime','"$WORK/audit.exit"' in h)
check('all three exact binaries sealed','sha256sum "$LANGUAGE_BUILD/test_language" "$TOOLS_BUILD/test_tools" "$HOST"' in h)
check('public source-free projection',all(x not in h[h.index('collect()'):h.index('verdict()')] for x in ['cp "$WORK"','cat "$log"','sha256sum']))
source=p/'source'; expected=json.loads((p/'recovered-files.json').read_text())
check('all recovered files have exact Git blob identity',all(hashlib.sha1(b'blob '+str(len((source/f).read_bytes())).encode()+b'\0'+(source/f).read_bytes()).hexdigest()==oid['blob'] for f,oid in expected.items()))
transport=p.parent/'recovered-transport-validation/source'
counts=lambda f:len(re.findall(r'^\s*RUN_TEST_CASE\(', (transport/f).read_text(),re.M))
check('snapshot exactly eight local cases',counts('test/language/package_snapshot_chibi.c')==8)
check('snapshot includes all eight resolver cases',counts('test/language/package_resolution.c')==8 and 'test_language_package_resolution_observed();' in (transport/'test/language/package_snapshot_chibi.c').read_text())
check('artifact exactly fifteen tooling cases',counts('test/tools/compiler_artifact.c')==15)
check('artifact exactly two producer cases',counts('test/language/compiler_artifact_chibi.c')==2)
check('supervisor remains sixty seconds','LIMIT = 60\n' in (source/'tools/test_policy.py').read_text())
check('child cap remains ten seconds','TOOL_RUN_SECONDS 10' in (transport/'test/tools/fixture.h').read_text())
subprocess.run(['bash','-n',str(p/'proposal/reader-state-validation.sh')],check=True)
check('helper parses',True)
for x in s:
 if 'run' in x:subprocess.run(['bash','-n'],input=x['run'],text=True,check=True)
check('all public shell fragments parse',True)

check('workflow retry denied', '$GITHUB_RUN_ATTEMPT' in s[0]['run'] and '${GITHUB_RUN_ATTEMPT:-}' in h)
check('existing workflow only', (p/'proposal/toolchain-m5-unit-analysis.yml').exists() and not (p/'proposal/toolchain-m5-transport.yml').exists())
check('shared-control ordinary CI exclusion retained', "head.ref != 'codex/host-m5-unit-validation-20261018'" in (p/'reference-studio-ci.yml').read_text())
check('no additional public branch', 'codex/host-m5-transport-validation-20261018' not in h+(p/'proposal/toolchain-m5-unit-analysis.yml').read_text())
check('single reused audit implementation', '"$ROOT/.github/scripts/transport-boundary-audit.py"' in h and not (p/'audit').exists())
reader=(source/'test/language/signature_reader_chibi.c').read_text()
oldreader=(p/'reference-parent-reader.c').read_text()
newincludes=['#include "package_graph_chibi_source.h"\n','#include "package_paths_chibi_source.h"\n','#include "package_routes_chibi_source.h"\n','#include "package_snapshot_chibi_source.h"\n','#include "package_syntax_chibi_source.h"\n','#include "toolchain/compiler_syntax.h"\n']
prefix=reader[:reader.index('/* Separate proposed selector in this owner:')]
for inc in newincludes: prefix=prefix.replace(inc,'')
check('old reader owner unchanged beyond six includes', prefix.rstrip()==oldreader.rstrip())
check('old reader complete four cases',len(re.findall(r'RUN_TEST_CASE\(',oldreader[oldreader.index('void test_language_signature_reader_chibi()'):]))==4)
check('new reader complete three cases',len(re.findall(r'RUN_TEST_CASE\(',reader[reader.index('void test_language_snapshot_reader_chibi()'):]))==3)
policy=ast.parse((source/'tools/test_policy.py').read_text())
oldpolicy=ast.parse((p/'reference-parent-policy.py').read_text())
functions=lambda x:[ast.dump(n,include_attributes=False) for n in x.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))]
check('production supervisor functions unchanged',functions(policy)==functions(oldpolicy))
state=(source/'tools/compiler/analysis_state/State.chibi').read_text()
check('state has no native semantic callback',all(x not in state for x in ['compiler_syntax_parse','compiler_json','extern ','native ','Analyze(']))
check('state imports only retained snapshot reader syntax',re.findall(r'^import \w+ "([^"]+)"',state,re.M)==['project:source_snapshot','project:signature_reader','project:syntax_diagnostics'])
check('negative links preserved', 'if (link < 0) { return link; }' in state)
check('all topology links localized', all('LocalLink(item.'+x+', document.node_start)' in state for x in ['parent','first_child','next_sibling']))
check('explicit syntax root localized','document.syntax_root - document.node_start' in state)
check('raw flags and text carried','item.is_named' in state and 'item.is_extra' in state and 'document.text)' in state)
check('adapter production source only State','analysis_state/State.chibi' in (source/'test/language/CMakeLists.txt').read_text())
check('new call assertions fixed',all(x in reader for x in ['snapshot_calls == 6 && map_calls == 14 && view_calls == 20','reader_calls == 24 && snapshot_parses == 7']))
check('closure strict cap unchanged','total < 128 * 1024 && sizeof ANALYSIS_STATE_CHIBI_SOURCE < 8192' in reader)
check('snapshot supplied budget fixed','values, 4, 3000000' in reader)
check('readers supplied budget fixed',reader.count('"Signature", values, 5, 500000')==2)
check('both backends preserved', 'for (int b = 0; b < 2; b++)' in reader and 'TEST_COMPILED_BACKEND' in (transport/'test/language/compiler_fixture.c').read_text())
check('snapshot owner retired before reading',reader.index('/* Views and maps must own their outputs after the input snapshot dies. */')<reader.index('/* Each oracle tree is parsed once, shared read-only across both backends. */'))
check('views retired before result comparison','arena_free(&view_storage[b][file]);' in reader and 'pin_value_equal(&direct_result, &adapted_result)' in reader)

resource=json.loads((p/'resource-manifest.json').read_text())
check('closure sources exactly fourteen',len(resource['measured_source_closure'])==14)
check('closure source bytes recomputed',sum(len((source/x['path']).read_bytes()) for x in resource['measured_source_closure'])==resource['closure_bytes']==129840)
check('closure source hashes exact',all(hashlib.sha256((source/x['path']).read_bytes()).hexdigest()==x['sha256'] for x in resource['measured_source_closure']))
check('strict source caps retained',all(x['bytes']<x['exclusive_source_cap_bytes'] for x in resource['measured_source_closure']) and resource['closure_bytes']<131072 and resource['state_bytes_including_c_terminator']<8192)
check('resource accounting exact',resource['workload']['total_authored_calls']==6+14+20+24==64 and resource['workload']['total_parses']==28+7+14==49)
check('shared transport sources match recorded blobs',all(hashlib.sha1(b'blob '+str(len((transport/f).read_bytes())).encode()+b'\0'+(transport/f).read_bytes()).hexdigest()==oid for f,oid in json.loads((transport.parent/'recovered-files.json').read_text()).items()))
admission=json.loads((p/'admission.json').read_text())
check('shared audit dependency matches pin',hashlib.sha256((p/admission['reused_audit']['local_path']).read_bytes()).hexdigest()==admission['reused_audit']['sha256'])
check('unadmitted future identity kept unresolved',not admission['independent_runtime_admission'] and admission['future_private_candidate_sha'] is None and admission['future_control_sha'] is None and not admission['slot_release_verified'])
import fnmatch
publish=yaml.safe_load((p/'reference-studio-publish.yml').read_text())
patterns=publish.get('on',publish.get(True))['pull_request']['paths']
check('replacement workflow misses publish filters',not any(fnmatch.fnmatch('.github/workflows/toolchain-m5-unit-analysis.yml',x) for x in patterns))
refs=json.loads((p/'reference-identities.json').read_text())
check('all reference files match verified Git blob ids',all(hashlib.sha1(b'blob '+str(len((p/f).read_bytes())).encode()+b'\0'+(p/f).read_bytes()).hexdigest()==x['git_blob_sha'] for f,x in refs.items()))
report={'checks':len(checks),'passed':checks,'target_build_or_runtime_executed':False}
(p/'workflow-check-results.json').write_text(json.dumps(report,indent=2)+'\n'); print(json.dumps(report,indent=2))
